import { randomUUID } from "node:crypto";
import { expect, type Page, test } from "@playwright/test";
import { enrollConsoleOwner } from "./owner-fixture.js";

test.beforeEach(async ({ page, baseURL }, testInfo) => {
  await enrollConsoleOwner(page, baseURL, testInfo.project.metadata);
});

async function projectAndAccess(page: Page) {
  const name = `Accès e2e ${randomUUID().slice(0, 8)}`;
  await page.goto("/projects/new");
  await page.getByLabel("Nom du projet", { exact: true }).fill(name);
  await page.getByRole("button", { name: "Enregistrer le projet", exact: true }).click();
  await expect(page.getByRole("heading", { name, exact: true })).toBeVisible();
  await page
    .getByRole("complementary", { name: "Barre latérale" })
    .getByRole("link", { name: "Réglages", exact: true })
    .click();
  await page
    .getByRole("navigation", { name: "Sections des réglages" })
    .getByRole("link", { name: "Secrets et services", exact: true })
    .click();
  await expect(
    page.getByRole("heading", { name: "Secrets et identités de service", exact: true }),
  ).toBeVisible();
  await expect(
    page.getByRole("heading", { name: "OpenBao non configuré", exact: true }),
  ).toBeVisible();
  const form = page.getByRole("form", { name: "Créer une identité de service", exact: true });
  await form.getByLabel("Projet", { exact: true }).selectOption({ label: name });
  await form.getByLabel("Environnement", { exact: true }).selectOption({ label: "Développement" });
  return form;
}

test("T-AC-14 manages scoped service metadata and revokes access without revealing values", async ({
  page,
}) => {
  const form = await projectAndAccess(page);
  const identityName = `Runtime ${randomUUID().slice(0, 8)}`;
  const slotName = "Connexion privée application";
  await form.getByLabel("Nom de l’identité", { exact: true }).fill(identityName);
  await form.getByLabel("Usage", { exact: true }).selectOption({ label: "Application" });
  await form.getByRole("button", { name: "Créer l’identité", exact: true }).click();
  const card = page.getByRole("article", { name: `Identité ${identityName}`, exact: true });
  await expect(card).toBeVisible();
  await expect(card.getByText("Preuve privée à remettre", { exact: true })).toBeVisible();
  const slotForm = card.getByRole("form", {
    name: `Créer un emplacement pour ${identityName}`,
    exact: true,
  });
  await slotForm.getByLabel("Nom de l’emplacement", { exact: true }).fill(slotName);
  await slotForm.getByRole("button", { name: "Créer l’emplacement", exact: true }).click();
  await expect(card.getByText(slotName, { exact: true })).toBeVisible();
  await expect(card.getByText(/Vide · version active — · candidat —/)).toBeVisible();
  await page.reload();
  await expect(card.getByText(slotName, { exact: true })).toBeVisible();
  await page.screenshot({ path: "artifacts/access-desktop.png", fullPage: true });

  await card.getByRole("button", { name: "Révoquer l’identité", exact: true }).click();

  await expect(card.getByText(/Application · Révoqué · révision 2/)).toBeVisible();
  await expect(
    card.getByRole("button", { name: "Révoquer l’identité", exact: true }),
  ).toBeDisabled();
  await expect(
    card.getByRole("button", { name: "Créer l’emplacement", exact: true }),
  ).toBeDisabled();
  await expect(
    page.getByRole("status").filter({ hasText: "L’accès au broker est révoqué." }),
  ).toBeVisible();
  await page.setViewportSize({ width: 390, height: 844 });
  await expect(
    page.getByRole("heading", { name: "Secrets et identités de service", exact: true }),
  ).toBeVisible();
  expect(await page.evaluate(() => document.documentElement.scrollWidth <= window.innerWidth)).toBe(
    true,
  );
  await page.screenshot({ path: "artifacts/access-mobile.png", fullPage: true });
});

test("T-AC-15 requires and retains a dedicated worker binding for a migration identity", async ({
  page,
}) => {
  const form = await projectAndAccess(page);
  const identityName = `Migration ${randomUUID().slice(0, 8)}`;
  const workerId = "migration-fixture-worker";
  await form.getByLabel("Nom de l’identité", { exact: true }).fill(identityName);
  await form.getByLabel("Usage", { exact: true }).selectOption({ label: "Migration" });
  await expect(form.getByLabel("Worker autorisé", { exact: true })).toHaveAttribute("required", "");
  await form.getByLabel("Worker autorisé", { exact: true }).fill(workerId);

  await form.getByRole("button", { name: "Créer l’identité", exact: true }).click();

  const card = page.getByRole("article", { name: `Identité ${identityName}`, exact: true });
  await expect(card.getByText(/Migration · Actif/)).toBeVisible();
  await expect(
    card.getByText(`Preuve privée à remettre · Worker ${workerId}`, { exact: true }),
  ).toBeVisible();
  await page.reload();
  await expect(
    card.getByText(`Preuve privée à remettre · Worker ${workerId}`, { exact: true }),
  ).toBeVisible();
});
